    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_parameter('localIpAddr', self.enb_ent_config['enb_ipv6'])
        self.set_parameter('localIpPrefixLength', self.enb_ent_config['enb_ipv6_prefix_length'])
        self.set_parameter('ipAddressAllocationMethod', "MANUAL")
